            cmd_DG2_cut_in = 0;
            cmd_DG2_cut_out = 1;
            cmd_load_cut_in = 1;
            cmd_load_cut_out = 0;
        }
    }

    state LNGBatteryAssist {
        enter {
            Pgen_req = Pgmax;
            Pbat_discharge = PL - Ppv - Pw - Pgmax;
            Pbat_charge = 0;
            Pspare = 0;
            cmd_LNG_cut_in = 1;
