                Pbat_discharge = Pbatmax;
            } else {
                Pbat_discharge = 0;
            }
            Pbat_charge = 0;
            Pspare = 0;
            cmd_generation_cut = 1;
            cmd_load_cut = 1;
            cmd_LNG_cut_in = 1;
            cmd_LNG_cut_out = 0;
            cmd_DG1_cut_in = 1;
            cmd_DG1_cut_out = 0;
            cmd_DG2_cut_in = 1;
            cmd_DG2_cut_out = 0;
            cmd_load_cut_in = 0;
            cmd_load_cut_out = 1;
